-- Generated from the reviewed psychometric contracts. Scoring keys stay in private schema.
begin;

create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

insert into public.app_modules (code, name, route, description, sort_order, is_active)
values ('gestion_psicolaboral','Gestión Psicolaboral','/gestion-psicolaboral','Centro de mando de evaluaciones psicolaborales para candidatos activos.',35,true)
on conflict (code) do update set name=excluded.name, route=excluded.route, description=excluded.description, sort_order=excluded.sort_order, is_active=true, updated_at=timezone('utc',now());

with desired(role_code) as (values ('admin'),('reclutamiento'))
insert into public.role_module_access(role_code,module_code,can_view)
select d.role_code,'gestion_psicolaboral',true from desired d join public.app_roles r on r.code=d.role_code and r.is_active
on conflict(role_code,module_code) do update set can_view=true;

delete from public.role_module_access where module_code='gestion_psicolaboral' and role_code not in ('admin','reclutamiento');

create table private.psychometric_instrument_versions (
  id uuid primary key default gen_random_uuid(), instrument_code text not null, name text not null, short_name text not null,
  content_version text not null, scoring_version text not null, instructions text not null, response_options jsonb not null,
  questions jsonb not null, scoring_key jsonb not null, content_sha256 text not null, sort_order integer not null,
  is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()),
  unique(instrument_code,content_version,scoring_version)
);
create unique index psychometric_one_active_version on private.psychometric_instrument_versions(instrument_code) where is_active;

create table private.psychometric_consent_versions (
  id uuid primary key default gen_random_uuid(), code text not null, version text not null, title text not null, document_date date not null,
  body text not null, content_sha256 text not null, document_sha256 text not null, is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), unique(code,version)
);

create table private.psychometric_assessments (
  id uuid primary key default gen_random_uuid(), public_id uuid not null default gen_random_uuid() unique,
  recruitment_case_candidate_id uuid not null references public.recruitment_case_candidates(id) on delete restrict,
  email_snapshot text not null, delivery_status text not null default 'preparing' check(delivery_status in ('preparing','sent','failed')),
  execution_status text not null default 'not_started' check(execution_status in ('not_started','in_progress','completed','expired','cancelled')),
  decision text not null default 'pending' check(decision in ('pending','approved','rejected')),
  invite_hash text not null unique, invite_consumed_at timestamptz, session_hash text unique, issued_at timestamptz,
  invite_expires_at timestamptz, started_at timestamptz, deadline_at timestamptz, completed_at timestamptz, decided_at timestamptz, decided_by uuid,
  provider_message_id text, last_error text, idempotency_key text not null,
  certificate_status text not null default 'not_ready' check(certificate_status in ('not_ready','queued','processing','generated','failed')),
  certificate_bucket text, certificate_path text, certificate_sha256 text, certificate_generated_at timestamptz,
  certificate_claim_token uuid, certificate_claimed_at timestamptz,
  created_by uuid not null, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()),
  unique(created_by,idempotency_key)
);
create unique index psychometric_one_open_assessment on private.psychometric_assessments(recruitment_case_candidate_id)
where execution_status not in ('completed','expired','cancelled') and decision <> 'rejected';

create table private.psychometric_assessment_instruments (
  id uuid primary key default gen_random_uuid(), assessment_id uuid not null references private.psychometric_assessments(id) on delete cascade,
  instrument_version_id uuid not null references private.psychometric_instrument_versions(id), sort_order integer not null,
  status text not null default 'not_started' check(status in ('not_started','in_progress','completed')),
  responses jsonb not null default '{}'::jsonb, response_revision integer not null default 0, response_sha256 text,
  result jsonb, result_sha256 text, started_at timestamptz, completed_at timestamptz, updated_at timestamptz not null default timezone('utc',now()),
  unique(assessment_id,instrument_version_id), unique(assessment_id,sort_order)
);

create table private.psychometric_consent_acceptances (
  id uuid primary key default gen_random_uuid(), assessment_id uuid not null references private.psychometric_assessments(id) on delete cascade,
  consent_version_id uuid not null references private.psychometric_consent_versions(id), accepted_at timestamptz not null default timezone('utc',now()),
  ip_hash text, user_agent_hash text, unique(assessment_id,consent_version_id)
);
create table private.psychometric_assessment_consents (
  assessment_id uuid not null references private.psychometric_assessments(id) on delete cascade,
  consent_version_id uuid not null references private.psychometric_consent_versions(id),
  sort_order integer not null,
  primary key(assessment_id,consent_version_id), unique(assessment_id,sort_order)
);
create table private.psychometric_access_rate_limits (
  scope_key text primary key, window_started_at timestamptz not null default timezone('utc',now()), attempt_count integer not null default 0, updated_at timestamptz not null default timezone('utc',now())
);
create table private.psychometric_audit_log (
  id bigint generated always as identity primary key, assessment_id uuid, instrument_id uuid, event_type text not null,
  actor_user_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default timezone('utc',now())
);

alter table private.psychometric_instrument_versions enable row level security;
alter table private.psychometric_consent_versions enable row level security;
alter table private.psychometric_assessments enable row level security;
alter table private.psychometric_assessment_instruments enable row level security;
alter table private.psychometric_consent_acceptances enable row level security;
alter table private.psychometric_assessment_consents enable row level security;
alter table private.psychometric_access_rate_limits enable row level security;
alter table private.psychometric_audit_log enable row level security;
revoke all on all tables in schema private from public,anon,authenticated;
grant all on all tables in schema private to service_role;

insert into private.psychometric_instrument_versions(instrument_code,name,short_name,content_version,scoring_version,instructions,response_options,questions,scoring_key,content_sha256,sort_order,is_active)
values
  ('IPIP16_105', 'Evaluación de Personalidad IPIP-16', 'IPIP-16/105', 'IPIP16-105-esCL-v0.2-draft', 'IPIP16-105-score-v0.2', 'Responda pensando en cómo es usted habitualmente. Para cada afirmación marque una alternativa. No existen respuestas correctas o incorrectas.', '[{"value":1,"label":"Muy inexacto"},{"value":2,"label":"Inexacto"},{"value":3,"label":"Ni exacto ni inexacto"},{"value":4,"label":"Exacto"},{"value":5,"label":"Muy exacto"}]'::jsonb, '[{"order":1,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Know how to comfort others.","text":"Sé cómo consolar a otras personas cuando lo necesitan.","sourceIndex":1},{"order":2,"code":"INT","scale":"Análisis y aprendizaje","reverse":true,"original":"Get confused easily.","text":"Me confundo con facilidad.","sourceIndex":10},{"order":3,"code":"EST","scale":"Estabilidad emocional","reverse":false,"original":"Feel comfortable with myself.","text":"Me siento bien conmigo mismo(a).","sourceIndex":2},{"order":4,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Wait for others to lead the way.","text":"Espero que otras personas indiquen el camino a seguir.","sourceIndex":7},{"order":5,"code":"GRE","scale":"Sociabilidad grupal","reverse":false,"original":"Am the life of the party.","text":"Suelo animar las reuniones sociales.","sourceIndex":1},{"order":6,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Resist authority.","text":"Me resisto a seguir indicaciones de autoridad.","sourceIndex":6},{"order":7,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Feel comfortable around people.","text":"Me siento cómodo(a) cuando estoy con otras personas.","sourceIndex":1},{"order":8,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Do not enjoy watching dance performances.","text":"No disfruto ver espectáculos de danza.","sourceIndex":7},{"order":9,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Find it hard to forgive others.","text":"Me cuesta perdonar a otras personas.","sourceIndex":1},{"order":10,"code":"IMA","scale":"Imaginación","reverse":true,"original":"Do things by the book.","text":"Prefiero hacer las cosas exactamente según lo establecido.","sourceIndex":8},{"order":11,"code":"RES","scale":"Reserva personal","reverse":false,"original":"Reveal little about myself.","text":"Revelo poco sobre mí.","sourceIndex":1},{"order":12,"code":"APR","scale":"Aprensión","reverse":true,"original":"Don''t worry about things that have already happened.","text":"No me preocupo por cosas que ya ocurrieron.","sourceIndex":8},{"order":13,"code":"APE","scale":"Apertura a ideas y cambio","reverse":false,"original":"Love to think up new ways of doing things.","text":"Me encanta imaginar nuevas maneras de hacer las cosas.","sourceIndex":2},{"order":14,"code":"AUT","scale":"Autosuficiencia","reverse":true,"original":"Enjoy being part of a group.","text":"Disfruto formar parte de un grupo.","sourceIndex":8},{"order":15,"code":"ORD","scale":"Orden y perfeccionismo","reverse":false,"original":"Get chores done right away.","text":"Realizo de inmediato las tareas que debo hacer.","sourceIndex":2},{"order":16,"code":"TEN","scale":"Tensión e irritabilidad","reverse":true,"original":"Am not easily annoyed.","text":"No me molesto con facilidad.","sourceIndex":8},{"order":17,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Enjoy bringing people together.","text":"Disfruto reunir a las personas.","sourceIndex":2},{"order":18,"code":"INT","scale":"Análisis y aprendizaje","reverse":true,"original":"Have a poor vocabulary.","text":"Tengo un vocabulario limitado.","sourceIndex":12},{"order":19,"code":"EST","scale":"Estabilidad emocional","reverse":false,"original":"Readily overcome setbacks.","text":"Me recupero rápidamente después de una dificultad.","sourceIndex":3},{"order":20,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Never challenge things.","text":"Evito cuestionar la manera en que se hacen las cosas.","sourceIndex":8},{"order":21,"code":"GRE","scale":"Sociabilidad grupal","reverse":false,"original":"Love large parties.","text":"Disfruto las reuniones con muchas personas.","sourceIndex":2},{"order":22,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Break rules.","text":"Rompo las reglas.","sourceIndex":7},{"order":23,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Talk to a lot of different people at parties.","text":"En reuniones converso con muchas personas diferentes.","sourceIndex":2},{"order":24,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Do not like poetry.","text":"No me gusta la poesía.","sourceIndex":8},{"order":25,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Suspect hidden motives in others.","text":"Sospecho que otras personas pueden tener intenciones ocultas.","sourceIndex":2},{"order":26,"code":"IMA","scale":"Imaginación","reverse":true,"original":"Seldom daydream.","text":"Rara vez sueño despierto(a).","sourceIndex":9},{"order":27,"code":"RES","scale":"Reserva personal","reverse":false,"original":"Bottle up my feelings.","text":"Guardo mis sentimientos para mí.","sourceIndex":4},{"order":28,"code":"APR","scale":"Aprensión","reverse":true,"original":"Am not easily bothered by things.","text":"Las cosas no me afectan con facilidad.","sourceIndex":9},{"order":29,"code":"APE","scale":"Apertura a ideas y cambio","reverse":false,"original":"Enjoy hearing new ideas.","text":"Disfruto escuchar ideas nuevas.","sourceIndex":3},{"order":30,"code":"AUT","scale":"Autosuficiencia","reverse":true,"original":"Enjoy teamwork.","text":"Disfruto trabajar en equipo.","sourceIndex":9},{"order":31,"code":"ORD","scale":"Orden y perfeccionismo","reverse":false,"original":"Like order.","text":"Me gusta el orden.","sourceIndex":3},{"order":32,"code":"TEN","scale":"Tensión e irritabilidad","reverse":true,"original":"Try to forgive and forget.","text":"Trato de perdonar y dejar atrás los problemas.","sourceIndex":9},{"order":33,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Take an interest in other people''s lives.","text":"Me intereso por lo que ocurre en la vida de otras personas.","sourceIndex":4},{"order":34,"code":"INT","scale":"Análisis y aprendizaje","reverse":true,"original":"Skip difficult words while reading.","text":"Cuando leo, paso por alto las palabras difíciles.","sourceIndex":13},{"order":35,"code":"EST","scale":"Estabilidad emocional","reverse":false,"original":"Am relaxed most of the time.","text":"La mayor parte del tiempo me siento tranquilo(a).","sourceIndex":4},{"order":36,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Let others make the decisions.","text":"Dejo que otras personas tomen las decisiones.","sourceIndex":9},{"order":37,"code":"GRE","scale":"Sociabilidad grupal","reverse":false,"original":"Amuse my friends.","text":"Me gusta entretener y hacer reír a mis amistades.","sourceIndex":5},{"order":38,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Oppose authority.","text":"Suelo oponerme a la autoridad.","sourceIndex":9},{"order":39,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Make friends easily.","text":"Hago amistades con facilidad.","sourceIndex":4},{"order":40,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Dislike works of fiction.","text":"No me gustan las obras de ficción.","sourceIndex":9},{"order":41,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Am wary of others.","text":"Me mantengo alerta frente a las intenciones de otras personas.","sourceIndex":3},{"order":42,"code":"IMA","scale":"Imaginación","reverse":true,"original":"Seldom get lost in thought.","text":"Rara vez me pierdo en mis pensamientos.","sourceIndex":10},{"order":43,"code":"RES","scale":"Reserva personal","reverse":false,"original":"Keep my thoughts to myself.","text":"Prefiero guardar mis pensamientos para mí.","sourceIndex":5},{"order":44,"code":"APR","scale":"Aprensión","reverse":true,"original":"Don''t let others discourage me.","text":"No permito que otras personas me desanimen.","sourceIndex":10},{"order":45,"code":"APE","scale":"Apertura a ideas y cambio","reverse":false,"original":"Prefer variety to routine.","text":"Prefiero la variedad antes que la rutina.","sourceIndex":5},{"order":46,"code":"AUT","scale":"Autosuficiencia","reverse":true,"original":"Can''t do without the company of others.","text":"Me cuesta estar sin la compañía de otras personas.","sourceIndex":10},{"order":47,"code":"ORD","scale":"Orden y perfeccionismo","reverse":false,"original":"Am exacting in my work.","text":"Soy exigente con la precisión de mi trabajo.","sourceIndex":5},{"order":48,"code":"TEN","scale":"Tensión e irritabilidad","reverse":true,"original":"Have a good word for everyone.","text":"Procuro referirme bien a las demás personas.","sourceIndex":10},{"order":49,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Make people feel at ease.","text":"Hago que otras personas se sientan cómodas conmigo.","sourceIndex":6},{"order":50,"code":"INT","scale":"Análisis y aprendizaje","reverse":false,"original":"Tend to analyze things.","text":"Tiendo a analizar las cosas.","sourceIndex":3},{"order":51,"code":"EST","scale":"Estabilidad emocional","reverse":true,"original":"Have frequent mood swings.","text":"Tengo cambios de ánimo frecuentes.","sourceIndex":6},{"order":52,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Let myself be pushed around.","text":"Permito que otras personas me impongan lo que debo hacer.","sourceIndex":10},{"order":53,"code":"GRE","scale":"Sociabilidad grupal","reverse":true,"original":"Seldom joke around.","text":"Rara vez bromeo con otras personas.","sourceIndex":7},{"order":54,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Know how to get around the rules.","text":"Sé cómo eludir las reglas cuando me conviene.","sourceIndex":10},{"order":55,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Start conversations.","text":"Inicio conversaciones con otras personas.","sourceIndex":5},{"order":56,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Rarely notice my emotional reactions.","text":"Rara vez noto mis propias reacciones emocionales.","sourceIndex":10},{"order":57,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Believe that people seldom tell you the whole truth.","text":"Creo que las personas pocas veces cuentan toda la verdad.","sourceIndex":5},{"order":58,"code":"IMA","scale":"Imaginación","reverse":false,"original":"Like to get lost in thought.","text":"Me gusta perderme en mis pensamientos.","sourceIndex":2},{"order":59,"code":"RES","scale":"Reserva personal","reverse":true,"original":"Am open about myself to others.","text":"Hablo abiertamente sobre mí con otras personas.","sourceIndex":6},{"order":60,"code":"APR","scale":"Aprensión","reverse":false,"original":"Am afraid that I will do the wrong thing.","text":"Temo hacer algo incorrecto.","sourceIndex":1},{"order":61,"code":"APE","scale":"Apertura a ideas y cambio","reverse":true,"original":"Avoid philosophical discussions.","text":"Evito las conversaciones filosóficas.","sourceIndex":6},{"order":62,"code":"AUT","scale":"Autosuficiencia","reverse":false,"original":"Prefer to do things by myself.","text":"Prefiero hacer las cosas por mi cuenta.","sourceIndex":2},{"order":63,"code":"ORD","scale":"Orden y perfeccionismo","reverse":true,"original":"Am not bothered by disorder.","text":"El desorden no me molesta.","sourceIndex":7},{"order":64,"code":"TEN","scale":"Tensión e irritabilidad","reverse":false,"original":"Get irritated easily.","text":"Me irrito con facilidad.","sourceIndex":1},{"order":65,"code":"CAL","scale":"Calidez interpersonal","reverse":true,"original":"Don''t like to get involved in other people''s problems.","text":"Prefiero no involucrarme en los problemas de otras personas.","sourceIndex":8},{"order":66,"code":"INT","scale":"Análisis y aprendizaje","reverse":false,"original":"Learn quickly.","text":"Aprendo con rapidez.","sourceIndex":5},{"order":67,"code":"EST","scale":"Estabilidad emocional","reverse":true,"original":"Often feel blue.","text":"A menudo me siento desanimado(a).","sourceIndex":7},{"order":68,"code":"ASE","scale":"Asertividad","reverse":false,"original":"Take charge.","text":"Tomo la iniciativa para hacerme cargo.","sourceIndex":1},{"order":69,"code":"GRE","scale":"Sociabilidad grupal","reverse":true,"original":"Don''t like crowded events.","text":"No me gustan los eventos con mucha gente.","sourceIndex":8},{"order":70,"code":"CUM","scale":"Cumplimiento de normas","reverse":false,"original":"Believe laws should be strictly enforced.","text":"Considero importante que las normas se cumplan.","sourceIndex":1},{"order":71,"code":"SEG","scale":"Seguridad social","reverse":true,"original":"Find it difficult to approach others.","text":"Me cuesta acercarme a otras personas.","sourceIndex":6},{"order":72,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":false,"original":"Like to read.","text":"Me gusta leer.","sourceIndex":1},{"order":73,"code":"DES","scale":"Cautela interpersonal","reverse":true,"original":"Trust what people say.","text":"Confío en lo que las personas dicen.","sourceIndex":7},{"order":74,"code":"IMA","scale":"Imaginación","reverse":false,"original":"Enjoy wild flights of fantasy.","text":"Disfruto dejar volar libremente mi imaginación.","sourceIndex":3},{"order":75,"code":"RES","scale":"Reserva personal","reverse":true,"original":"Am open about my feelings.","text":"Expreso abiertamente mis sentimientos.","sourceIndex":7},{"order":76,"code":"APR","scale":"Aprensión","reverse":false,"original":"Worry about things.","text":"Me preocupo por las cosas.","sourceIndex":4},{"order":77,"code":"APE","scale":"Apertura a ideas y cambio","reverse":true,"original":"Rarely look for a deeper meaning in things.","text":"Rara vez busco un significado más profundo en las cosas.","sourceIndex":7},{"order":78,"code":"AUT","scale":"Autosuficiencia","reverse":false,"original":"Seek quiet.","text":"Busco espacios tranquilos.","sourceIndex":4},{"order":79,"code":"ORD","scale":"Orden y perfeccionismo","reverse":true,"original":"Leave my belongings around.","text":"Dejo mis pertenencias en cualquier lugar.","sourceIndex":9},{"order":80,"code":"TEN","scale":"Tensión e irritabilidad","reverse":false,"original":"Get angry easily.","text":"Me enojo con facilidad.","sourceIndex":2},{"order":81,"code":"CAL","scale":"Calidez interpersonal","reverse":true,"original":"Am not really interested in others.","text":"Las demás personas no me interesan mucho.","sourceIndex":9},{"order":82,"code":"INT","scale":"Análisis y aprendizaje","reverse":false,"original":"Reflect on things before acting.","text":"Reflexiono antes de actuar.","sourceIndex":7},{"order":83,"code":"EST","scale":"Estabilidad emocional","reverse":true,"original":"Am easily discouraged.","text":"Me desanimo con facilidad.","sourceIndex":10},{"order":84,"code":"ASE","scale":"Asertividad","reverse":false,"original":"Say what I think.","text":"Expreso lo que pienso.","sourceIndex":3},{"order":85,"code":"GRE","scale":"Sociabilidad grupal","reverse":true,"original":"Dislike loud music.","text":"Me desagradan los ambientes con música fuerte.","sourceIndex":10},{"order":86,"code":"CUM","scale":"Cumplimiento de normas","reverse":false,"original":"Try to follow the rules.","text":"Trato de seguir las reglas.","sourceIndex":2},{"order":87,"code":"SEG","scale":"Seguridad social","reverse":true,"original":"Often feel uncomfortable around others.","text":"A menudo me siento incómodo(a) cuando estoy con otras personas.","sourceIndex":7},{"order":88,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":false,"original":"Enjoy discussing movies and books with others.","text":"Disfruto conversar sobre películas y libros.","sourceIndex":2},{"order":89,"code":"DES","scale":"Cautela interpersonal","reverse":true,"original":"Believe that others have good intentions.","text":"Creo que las demás personas suelen tener buenas intenciones.","sourceIndex":9},{"order":90,"code":"IMA","scale":"Imaginación","reverse":false,"original":"Love to daydream.","text":"Me encanta soñar despierto(a).","sourceIndex":4},{"order":91,"code":"RES","scale":"Reserva personal","reverse":true,"original":"Am willing to talk about myself.","text":"Estoy dispuesto(a) a hablar sobre mí.","sourceIndex":10},{"order":92,"code":"APR","scale":"Aprensión","reverse":false,"original":"Spend time thinking about past mistakes.","text":"Dedico tiempo a pensar en errores del pasado.","sourceIndex":5},{"order":93,"code":"APE","scale":"Apertura a ideas y cambio","reverse":true,"original":"Am not interested in theoretical discussions.","text":"No me interesan las conversaciones teóricas.","sourceIndex":8},{"order":94,"code":"AUT","scale":"Autosuficiencia","reverse":false,"original":"Enjoy my privacy.","text":"Disfruto mi privacidad.","sourceIndex":7},{"order":95,"code":"ORD","scale":"Orden y perfeccionismo","reverse":true,"original":"Put off unpleasant tasks.","text":"Postergo las tareas que me resultan desagradables.","sourceIndex":10},{"order":96,"code":"TEN","scale":"Tensión e irritabilidad","reverse":false,"original":"Can''t stand being contradicted.","text":"Me cuesta tolerar que me contradigan.","sourceIndex":6},{"order":97,"code":"CAL","scale":"Calidez interpersonal","reverse":true,"original":"Try not to think about the needy.","text":"Trato de no pensar en quienes necesitan ayuda.","sourceIndex":10},{"order":98,"code":"INT","scale":"Análisis y aprendizaje","reverse":false,"original":"Weigh the pros against the cons.","text":"Evalúo las ventajas y desventajas antes de decidir.","sourceIndex":8},{"order":99,"code":"ASE","scale":"Asertividad","reverse":false,"original":"Take control of things.","text":"Asumo el control cuando una situación lo requiere.","sourceIndex":5},{"order":100,"code":"CUM","scale":"Cumplimiento de normas","reverse":false,"original":"Respect authority.","text":"Respeto a la autoridad legítima.","sourceIndex":4},{"order":101,"code":"SEG","scale":"Seguridad social","reverse":true,"original":"Keep in the background.","text":"Prefiero mantenerme en segundo plano.","sourceIndex":10},{"order":102,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":false,"original":"Cry during movies.","text":"Las películas pueden emocionarme hasta las lágrimas.","sourceIndex":5},{"order":103,"code":"DES","scale":"Cautela interpersonal","reverse":true,"original":"Believe that people are basically moral.","text":"Creo que, en general, las personas actúan correctamente.","sourceIndex":10},{"order":104,"code":"IMA","scale":"Imaginación","reverse":false,"original":"Do unexpected things.","text":"Hago cosas inesperadas.","sourceIndex":7},{"order":105,"code":"APE","scale":"Apertura a ideas y cambio","reverse":true,"original":"Am not interested in abstract ideas.","text":"No me interesan las ideas abstractas.","sourceIndex":9}]'::jsonb, '{"kind":"ipip16","scales":[{"code":"CAL","name":"Calidez interpersonal"},{"code":"INT","name":"Análisis y aprendizaje"},{"code":"EST","name":"Estabilidad emocional"},{"code":"ASE","name":"Asertividad"},{"code":"GRE","name":"Sociabilidad grupal"},{"code":"CUM","name":"Cumplimiento de normas"},{"code":"SEG","name":"Seguridad social"},{"code":"SEN","name":"Sensibilidad estética y emocional"},{"code":"DES","name":"Cautela interpersonal"},{"code":"IMA","name":"Imaginación"},{"code":"RES","name":"Reserva personal"},{"code":"APR","name":"Aprensión"},{"code":"APE","name":"Apertura a ideas y cambio"},{"code":"AUT","name":"Autosuficiencia"},{"code":"ORD","name":"Orden y perfeccionismo"},{"code":"TEN","name":"Tensión e irritabilidad"}]}'::jsonb, encode(extensions.digest(convert_to('[{"order":1,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Know how to comfort others.","text":"Sé cómo consolar a otras personas cuando lo necesitan.","sourceIndex":1},{"order":2,"code":"INT","scale":"Análisis y aprendizaje","reverse":true,"original":"Get confused easily.","text":"Me confundo con facilidad.","sourceIndex":10},{"order":3,"code":"EST","scale":"Estabilidad emocional","reverse":false,"original":"Feel comfortable with myself.","text":"Me siento bien conmigo mismo(a).","sourceIndex":2},{"order":4,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Wait for others to lead the way.","text":"Espero que otras personas indiquen el camino a seguir.","sourceIndex":7},{"order":5,"code":"GRE","scale":"Sociabilidad grupal","reverse":false,"original":"Am the life of the party.","text":"Suelo animar las reuniones sociales.","sourceIndex":1},{"order":6,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Resist authority.","text":"Me resisto a seguir indicaciones de autoridad.","sourceIndex":6},{"order":7,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Feel comfortable around people.","text":"Me siento cómodo(a) cuando estoy con otras personas.","sourceIndex":1},{"order":8,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Do not enjoy watching dance performances.","text":"No disfruto ver espectáculos de danza.","sourceIndex":7},{"order":9,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Find it hard to forgive others.","text":"Me cuesta perdonar a otras personas.","sourceIndex":1},{"order":10,"code":"IMA","scale":"Imaginación","reverse":true,"original":"Do things by the book.","text":"Prefiero hacer las cosas exactamente según lo establecido.","sourceIndex":8},{"order":11,"code":"RES","scale":"Reserva personal","reverse":false,"original":"Reveal little about myself.","text":"Revelo poco sobre mí.","sourceIndex":1},{"order":12,"code":"APR","scale":"Aprensión","reverse":true,"original":"Don''t worry about things that have already happened.","text":"No me preocupo por cosas que ya ocurrieron.","sourceIndex":8},{"order":13,"code":"APE","scale":"Apertura a ideas y cambio","reverse":false,"original":"Love to think up new ways of doing things.","text":"Me encanta imaginar nuevas maneras de hacer las cosas.","sourceIndex":2},{"order":14,"code":"AUT","scale":"Autosuficiencia","reverse":true,"original":"Enjoy being part of a group.","text":"Disfruto formar parte de un grupo.","sourceIndex":8},{"order":15,"code":"ORD","scale":"Orden y perfeccionismo","reverse":false,"original":"Get chores done right away.","text":"Realizo de inmediato las tareas que debo hacer.","sourceIndex":2},{"order":16,"code":"TEN","scale":"Tensión e irritabilidad","reverse":true,"original":"Am not easily annoyed.","text":"No me molesto con facilidad.","sourceIndex":8},{"order":17,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Enjoy bringing people together.","text":"Disfruto reunir a las personas.","sourceIndex":2},{"order":18,"code":"INT","scale":"Análisis y aprendizaje","reverse":true,"original":"Have a poor vocabulary.","text":"Tengo un vocabulario limitado.","sourceIndex":12},{"order":19,"code":"EST","scale":"Estabilidad emocional","reverse":false,"original":"Readily overcome setbacks.","text":"Me recupero rápidamente después de una dificultad.","sourceIndex":3},{"order":20,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Never challenge things.","text":"Evito cuestionar la manera en que se hacen las cosas.","sourceIndex":8},{"order":21,"code":"GRE","scale":"Sociabilidad grupal","reverse":false,"original":"Love large parties.","text":"Disfruto las reuniones con muchas personas.","sourceIndex":2},{"order":22,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Break rules.","text":"Rompo las reglas.","sourceIndex":7},{"order":23,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Talk to a lot of different people at parties.","text":"En reuniones converso con muchas personas diferentes.","sourceIndex":2},{"order":24,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Do not like poetry.","text":"No me gusta la poesía.","sourceIndex":8},{"order":25,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Suspect hidden motives in others.","text":"Sospecho que otras personas pueden tener intenciones ocultas.","sourceIndex":2},{"order":26,"code":"IMA","scale":"Imaginación","reverse":true,"original":"Seldom daydream.","text":"Rara vez sueño despierto(a).","sourceIndex":9},{"order":27,"code":"RES","scale":"Reserva personal","reverse":false,"original":"Bottle up my feelings.","text":"Guardo mis sentimientos para mí.","sourceIndex":4},{"order":28,"code":"APR","scale":"Aprensión","reverse":true,"original":"Am not easily bothered by things.","text":"Las cosas no me afectan con facilidad.","sourceIndex":9},{"order":29,"code":"APE","scale":"Apertura a ideas y cambio","reverse":false,"original":"Enjoy hearing new ideas.","text":"Disfruto escuchar ideas nuevas.","sourceIndex":3},{"order":30,"code":"AUT","scale":"Autosuficiencia","reverse":true,"original":"Enjoy teamwork.","text":"Disfruto trabajar en equipo.","sourceIndex":9},{"order":31,"code":"ORD","scale":"Orden y perfeccionismo","reverse":false,"original":"Like order.","text":"Me gusta el orden.","sourceIndex":3},{"order":32,"code":"TEN","scale":"Tensión e irritabilidad","reverse":true,"original":"Try to forgive and forget.","text":"Trato de perdonar y dejar atrás los problemas.","sourceIndex":9},{"order":33,"code":"CAL","scale":"Calidez interpersonal","reverse":false,"original":"Take an interest in other people''s lives.","text":"Me intereso por lo que ocurre en la vida de otras personas.","sourceIndex":4},{"order":34,"code":"INT","scale":"Análisis y aprendizaje","reverse":true,"original":"Skip difficult words while reading.","text":"Cuando leo, paso por alto las palabras difíciles.","sourceIndex":13},{"order":35,"code":"EST","scale":"Estabilidad emocional","reverse":false,"original":"Am relaxed most of the time.","text":"La mayor parte del tiempo me siento tranquilo(a).","sourceIndex":4},{"order":36,"code":"ASE","scale":"Asertividad","reverse":true,"original":"Let others make the decisions.","text":"Dejo que otras personas tomen las decisiones.","sourceIndex":9},{"order":37,"code":"GRE","scale":"Sociabilidad grupal","reverse":false,"original":"Amuse my friends.","text":"Me gusta entretener y hacer reír a mis amistades.","sourceIndex":5},{"order":38,"code":"CUM","scale":"Cumplimiento de normas","reverse":true,"original":"Oppose authority.","text":"Suelo oponerme a la autoridad.","sourceIndex":9},{"order":39,"code":"SEG","scale":"Seguridad social","reverse":false,"original":"Make friends easily.","text":"Hago amistades con facilidad.","sourceIndex":4},{"order":40,"code":"SEN","scale":"Sensibilidad estética y emocional","reverse":true,"original":"Dislike works of fiction.","text":"No me gustan las obras de ficción.","sourceIndex":9},{"order":41,"code":"DES","scale":"Cautela interpersonal","reverse":false,"original":"Am wary of others.","text":"Me mantengo alerta frente a las intenciones de otras personas.","sourceIndex":3},{"order":42,"code":"IMA","scale":"Imaginación","reverse":true,"original":"Seldom get lost in thought.","text":"Rara vez me pierdo en mis pensamientos.","sourceIndex":10},{"order":43,"code":"RES","scale":"Reserva personal","reverse":false,"original":"Keep my thoughts to myself.","text":"Prefiero guardar mis pensamientos para mí.","sourceIndex":5},{"order":44,"code":"APR","scale":"Aprensión","reverse":true,"original":"Don''t let others discourage me.","text":"No permito que otras personas me desanimen.","sourceIndex":10},{"order":45,"code":"APE","scale":"Apertura a ideas y cambio","reverse":false,"origi