  ('IPIP_IPC_32', 'Evaluación Interpersonal IPIP-IPC', 'IPIP-IPC/32', 'IPIP-IPC-32-esCL-v0.2-draft', 'IPIP-IPC-32-score-v0.2', 'Describa cómo es usted habitualmente. Marque una alternativa para cada afirmación. No existen respuestas correctas o incorrectas.', '[{"value":1,"label":"Muy inexacto"},{"value":2,"label":"Inexacto"},{"value":3,"label":"Ni exacto ni inexacto"},{"value":4,"label":"Exacto"},{"value":5,"label":"Muy exacto"}]'::jsonb, '[{"order":1,"code":"FG","scale":"Reserva social","reverse":false,"original":"Am quiet around strangers","text":"Soy callado(a) cuando estoy con personas que no conozco."},{"order":2,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Speak softly","text":"Hablo en voz baja."},{"order":3,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Tolerate a lot from others","text":"Tolero muchas cosas de otras personas."},{"order":4,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Am interested in people","text":"Me intereso por las personas."},{"order":5,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Feel comfortable around people","text":"Me siento cómodo(a) cuando estoy con otras personas."},{"order":6,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Demand to be the center of interest","text":"Exijo ser el centro de atención."},{"order":7,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Cut others to pieces","text":"Critico duramente a otras personas."},{"order":8,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Believe people should fend for themselves","text":"Creo que cada persona debería arreglárselas por sí misma."},{"order":9,"code":"FG","scale":"Reserva social","reverse":false,"original":"Am a very private person","text":"Soy una persona muy reservada."},{"order":10,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Let others finish what they are saying","text":"Dejo que otras personas terminen de hablar."},{"order":11,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Take things as they come","text":"Tomo las cosas como vienen."},{"order":12,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Reassure others","text":"Tranquilizo a otras personas cuando lo necesitan."},{"order":13,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Start conversations","text":"Inicio conversaciones."},{"order":14,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Do most of the talking","text":"Hablo durante la mayor parte de una conversación."},{"order":15,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Contradict others","text":"Contradigo a otras personas."},{"order":16,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Don''t fall for sob-stories","text":"No me dejo convencer por historias que buscan provocar lástima."},{"order":17,"code":"FG","scale":"Reserva social","reverse":false,"original":"Don''t talk a lot","text":"No hablo mucho."},{"order":18,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Seldom toot my own horn","text":"Rara vez presumo de mis logros."},{"order":19,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Think of others first","text":"Pienso primero en las demás personas."},{"order":20,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Inquire about others'' well-being","text":"Me preocupo por saber cómo se sienten otras personas."},{"order":21,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Talk to a lot of different people at parties","text":"En reuniones converso con muchas personas diferentes."},{"order":22,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Speak loudly","text":"Hablo en voz alta."},{"order":23,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Snap at people","text":"Respondo de mala manera a las personas."},{"order":24,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Don''t put a lot of thought into things","text":"No reflexiono demasiado sobre las cosas."},{"order":25,"code":"FG","scale":"Reserva social","reverse":false,"original":"Have little to say","text":"Tengo poco que decir."},{"order":26,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Dislike being the center of attention","text":"No me gusta ser el centro de atención."},{"order":27,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Seldom stretch the truth","text":"Rara vez exagero o distorsiono la verdad."},{"order":28,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Get along well with others","text":"Me relaciono bien con otras personas."},{"order":29,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Love large parties","text":"Me encantan las reuniones con muchas personas."},{"order":30,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Demand attention","text":"Exijo que me presten atención."},{"order":31,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Have a sharp tongue","text":"Suelo expresarme de manera hiriente."},{"order":32,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Am not interested in other people''s problems","text":"No me interesan los problemas de otras personas."}]'::jsonb, '{"kind":"ipc32","params":{"LM":{"name":"Calidez cooperativa","mean":3.92,"sd":0.57,"angle":0},"NO":{"name":"Sociabilidad expresiva","mean":3.17,"sd":0.77,"angle":45},"PA":{"name":"Dominancia segura","mean":2.21,"sd":0.77,"angle":90},"BC":{"name":"Dominancia distante","mean":2.09,"sd":0.73,"angle":135},"DE":{"name":"Distancia afectiva","mean":2.24,"sd":0.69,"angle":180},"FG":{"name":"Reserva social","mean":2.81,"sd":0.8,"angle":225},"HI":{"name":"Baja dominancia","mean":3.19,"sd":0.7,"angle":270},"JK":{"name":"Modestia cooperativa","mean":3.8,"sd":0.57,"angle":315}}}'::jsonb, encode(extensions.digest(convert_to('[{"order":1,"code":"FG","scale":"Reserva social","reverse":false,"original":"Am quiet around strangers","text":"Soy callado(a) cuando estoy con personas que no conozco."},{"order":2,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Speak softly","text":"Hablo en voz baja."},{"order":3,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Tolerate a lot from others","text":"Tolero muchas cosas de otras personas."},{"order":4,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Am interested in people","text":"Me intereso por las personas."},{"order":5,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Feel comfortable around people","text":"Me siento cómodo(a) cuando estoy con otras personas."},{"order":6,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Demand to be the center of interest","text":"Exijo ser el centro de atención."},{"order":7,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Cut others to pieces","text":"Critico duramente a otras personas."},{"order":8,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Believe people should fend for themselves","text":"Creo que cada persona debería arreglárselas por sí misma."},{"order":9,"code":"FG","scale":"Reserva social","reverse":false,"original":"Am a very private person","text":"Soy una persona muy reservada."},{"order":10,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Let others finish what they are saying","text":"Dejo que otras personas terminen de hablar."},{"order":11,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Take things as they come","text":"Tomo las cosas como vienen."},{"order":12,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Reassure others","text":"Tranquilizo a otras personas cuando lo necesitan."},{"order":13,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Start conversations","text":"Inicio conversaciones."},{"order":14,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Do most of the talking","text":"Hablo durante la mayor parte de una conversación."},{"order":15,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Contradict others","text":"Contradigo a otras personas."},{"order":16,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Don''t fall for sob-stories","text":"No me dejo convencer por historias que buscan provocar lástima."},{"order":17,"code":"FG","scale":"Reserva social","reverse":false,"original":"Don''t talk a lot","text":"No hablo mucho."},{"order":18,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Seldom toot my own horn","text":"Rara vez presumo de mis logros."},{"order":19,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Think of others first","text":"Pienso primero en las demás personas."},{"order":20,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Inquire about others'' well-being","text":"Me preocupo por saber cómo se sienten otras personas."},{"order":21,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Talk to a lot of different people at parties","text":"En reuniones converso con muchas personas diferentes."},{"order":22,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Speak loudly","text":"Hablo en voz alta."},{"order":23,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Snap at people","text":"Respondo de mala manera a las personas."},{"order":24,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Don''t put a lot of thought into things","text":"No reflexiono demasiado sobre las cosas."},{"order":25,"code":"FG","scale":"Reserva social","reverse":false,"original":"Have little to say","text":"Tengo poco que decir."},{"order":26,"code":"HI","scale":"Baja dominancia","reverse":false,"original":"Dislike being the center of attention","text":"No me gusta ser el centro de atención."},{"order":27,"code":"JK","scale":"Modestia cooperativa","reverse":false,"original":"Seldom stretch the truth","text":"Rara vez exagero o distorsiono la verdad."},{"order":28,"code":"LM","scale":"Calidez cooperativa","reverse":false,"original":"Get along well with others","text":"Me relaciono bien con otras personas."},{"order":29,"code":"NO","scale":"Sociabilidad expresiva","reverse":false,"original":"Love large parties","text":"Me encantan las reuniones con muchas personas."},{"order":30,"code":"PA","scale":"Dominancia segura","reverse":false,"original":"Demand attention","text":"Exijo que me presten atención."},{"order":31,"code":"BC","scale":"Dominancia distante","reverse":false,"original":"Have a sharp tongue","text":"Suelo expresarme de manera hiriente."},{"order":32,"code":"DE","scale":"Distancia afectiva","reverse":false,"original":"Am not interested in other people''s problems","text":"No me interesan los problemas de otras personas."}]','utf8'),'sha256'),'hex'), 2, true),
  ('BARRATT_BIS11_30', 'Barratt BIS-11', 'Barratt', 'email-pdf-2026-08-13-v1', 'cetep-id15-recovered-v1', 'Las personas son diferentes en cuanto a la forma en que se comportan y piensan en distintas situaciones. Ésta es una prueba para medir algunas de las formas en que usted actúa y piensa. No se detenga demasiado tiempo en ninguna de las oraciones. Responda rápida y honestamente.', '[{"value":0,"label":"Raramente o nunca"},{"value":1,"label":"Ocasionalmente"},{"value":3,"label":"A menudo"},{"value":4,"label":"Siempre o casi siempre"}]'::jsonb, '[{"order":1,"text":"Planifico mis tareas con cuidado","reverse":true},{"order":2,"text":"Hago las cosas sin pensarlas","reverse":false},{"order":3,"text":"Casi nunca me tomo las cosas a pecho (no me perturbo con facilidad)","reverse":false},{"order":4,"text":"Mis pensamientos pueden tener gran velocidad (tengo pensamientos que van muy rápido en mi mente)","reverse":false},{"order":5,"text":"Planifico mis viajes con antelación","reverse":true},{"order":6,"text":"Soy una persona con autocontrol","reverse":true},{"order":7,"text":"Me concentro con facilidad (se me hace fácil concentrarme)","reverse":true},{"order":8,"text":"Ahorro con regularidad","reverse":true},{"order":9,"text":"Se me hace difícil estar quieto/a durante largos períodos de tiempo","reverse":false},{"order":10,"text":"Pienso las cosas cuidadosamente","reverse":true},{"order":11,"text":"Planifico para tener un trabajo fijo (me esfuerzo por asegurar que tendré dinero para pagar mis gastos)","reverse":true},{"order":12,"text":"Digo las cosas sin pensarlas","reverse":false},{"order":13,"text":"Me gusta pensar sobre problemas complicados (me gusta pensar sobre problemas complejos)","reverse":true},{"order":14,"text":"Cambio de trabajo frecuentemente (no me quedo en el mismo trabajo durante largos períodos de tiempo)","reverse":false},{"order":15,"text":"Actúo impulsivamente","reverse":false},{"order":16,"text":"Me aburro con facilidad tratando de resolver problemas en mi mente (me aburre pensar en algo por demasiado tiempo)","reverse":false},{"order":17,"text":"Visito al médico y al dentista con regularidad","reverse":true},{"order":18,"text":"Hago las cosas en el momento en que se me ocurren","reverse":false},{"order":19,"text":"Soy una persona que piensa sin distraerse (puedo enfocar mi mente en una sola cosa por mucho tiempo)","reverse":true},{"order":20,"text":"Cambio de vivienda a menudo (me mudo con frecuencia o no me gusta vivir en el mismo sitio por mucho tiempo)","reverse":false},{"order":21,"text":"Compro cosas impulsivamente","reverse":false},{"order":22,"text":"Termino lo que empiezo","reverse":true},{"order":23,"text":"Camino y me muevo con rapidez","reverse":false},{"order":24,"text":"Resuelvo los problemas experimentando (resuelvo los problemas empleando una posible solución y viendo si funciona)","reverse":false},{"order":25,"text":"Gasto en efectivo o a crédito más de lo que gano (gasto más de lo que gano)","reverse":false},{"order":26,"text":"Hablo rápido","reverse":false},{"order":27,"text":"Tengo pensamientos extraños cuando estoy pensando (a veces tengo pensamientos irrelevantes cuando pienso)","reverse":false},{"order":28,"text":"Me interesa más el presente que el futuro","reverse":false},{"order":29,"text":"Me siento inquieto/a en clases o charlas (me siento inquieto/a si tengo que oír a alguien hablar durante un largo período de tiempo)","reverse":false},{"order":30,"text":"Planifico el futuro (me interesa más el futuro que el presente)","reverse":true}]'::jsonb, '{"kind":"barratt","reverseItems":[1,5,6,7,8,10,11,13,17,19,22,30]}'::jsonb, encode(extensions.digest(convert_to('[{"order":1,"text":"Planifico mis tareas con cuidado","reverse":true},{"order":2,"text":"Hago las cosas sin pensarlas","reverse":false},{"order":3,"text":"Casi nunca me tomo las cosas a pecho (no me perturbo con facilidad)","reverse":false},{"order":4,"text":"Mis pensamientos pueden tener gran velocidad (tengo pensamientos que van muy rápido en mi mente)","reverse":false},{"order":5,"text":"Planifico mis viajes con antelación","reverse":true},{"order":6,"text":"Soy una persona con autocontrol","reverse":true},{"order":7,"text":"Me concentro con facilidad (se me hace fácil concentrarme)","reverse":true},{"order":8,"text":"Ahorro con regularidad","reverse":true},{"order":9,"text":"Se me hace difícil estar quieto/a durante largos períodos de tiempo","reverse":false},{"order":10,"text":"Pienso las cosas cuidadosamente","reverse":true},{"order":11,"text":"Planifico para tener un trabajo fijo (me esfuerzo por asegurar que tendré dinero para pagar mis gastos)","reverse":true},{"order":12,"text":"Digo las cosas sin pensarlas","reverse":false},{"order":13,"text":"Me gusta pensar sobre problemas complicados (me gusta pensar sobre problemas complejos)","reverse":true},{"order":14,"text":"Cambio de trabajo frecuentemente (no me quedo en el mismo trabajo durante largos períodos de tiempo)","reverse":false},{"order":15,"text":"Actúo impulsivamente","reverse":false},{"order":16,"text":"Me aburro con facilidad tratando de resolver problemas en mi mente (me aburre pensar en algo por demasiado tiempo)","reverse":false},{"order":17,"text":"Visito al médico y al dentista con regularidad","reverse":true},{"order":18,"text":"Hago las cosas en el momento en que se me ocurren","reverse":false},{"order":19,"text":"Soy una persona que piensa sin distraerse (puedo enfocar mi mente en una sola cosa por mucho tiempo)","reverse":true},{"order":20,"text":"Cambio de vivienda a menudo (me mudo con frecuencia o no me gusta vivir en el mismo sitio por mucho tiempo)","reverse":false},{"order":21,"text":"Compro cosas impulsivamente","reverse":false},{"order":22,"text":"Termino lo que empiezo","reverse":true},{"order":23,"text":"Camino y me muevo con rapidez","reverse":false},{"order":24,"text":"Resuelvo los problemas experimentando (resuelvo los problemas empleando una posible solución y viendo si funciona)","reverse":false},{"order":25,"text":"Gasto en efectivo o a crédito más de lo que gano (gasto más de lo que gano)","reverse":false},{"order":26,"text":"Hablo rápido","reverse":false},{"order":27,"text":"Tengo pensamientos extraños cuando estoy pensando (a veces tengo pensamientos irrelevantes cuando pienso)","reverse":false},{"order":28,"text":"Me interesa más el presente que el futuro","reverse":false},{"order":29,"text":"Me siento inquieto/a en clases o charlas (me siento inquieto/a si tengo que oír a alguien hablar durante un largo período de tiempo)","reverse":false},{"order":30,"text":"Planifico el futuro (me interesa más el futuro que el presente)","reverse":true}]','utf8'),'sha256'),'hex'), 3, true),
  ('PRP_EMAIL_FORM_A_30', 'Escala P.R.P', 'PRP', 'email-docx-2026-08-13-v1', 'email-xls-2026-08-13-v1', 'Señale la opinión que mejor lo representa, de acuerdo con la afirmación que se le presenta. Sea lo más sincero posible y evite responder Indeciso cada vez que pueda hacerlo. No hay respuestas correctas o incorrectas.', '[{"value":1,"label":"Totalmente de Acuerdo"},{"value":2,"label":"De acuerdo"},{"value":3,"label":"Indeciso"},{"value":4,"label":"En Desacuerdo"},{"value":5,"label":"Totalmente en Desacuerdo"}]'::jsonb, '[{"order":1,"text":"Asistiría a un curso de prevención de accidentes de trabajo.","positive":true},{"order":2,"text":"Colaboraría en las acciones de prevención de accidentes de trabajo.","positive":true},{"order":3,"text":"Asistir a cursos de seguridad es perder el tiempo.","positive":false},{"order":4,"text":"La mayoría de los accidentes de trabajo se deben a mala suerte.","positive":false},{"order":5,"text":"Las reuniones mensuales de seguridad sólo sirven para perder el tiempo.","positive":false},{"order":6,"text":"Por mucho ruido que haya siempre se acostumbra uno.","positive":false},{"order":7,"text":"Cada uno tiene su destino y si se ha de accidentar, por más seguro que trabaje, se accidenta.","positive":false},{"order":8,"text":"Cada trabajador debe pedir su ropa de seguridad cuando le corresponde.","positive":true},{"order":9,"text":"No vale la pena usar protecciones porque el trabajo cunde poco.","positive":false},{"order":10,"text":"Aunque una Herramienta esta defectuosa con cuidado puede utilizarse.","positive":false},{"order":11,"text":"Colaboraría con la confección de carteles de seguridad.","positive":true},{"order":12,"text":"Para prevenirse de los accidentes no es necesario utilizar los elementos de protección personal.","positive":false},{"order":13,"text":"Los accidentes de trabajo solo ocurren a los demás","positive":false},{"order":14,"text":"El trabajador descuidado pone en peligro todos sus compañeros.","positive":true},{"order":15,"text":"Deberían organizarse más campañas de seguridad.","positive":true},{"order":16,"text":"Cuando trabajamos no es posible tener en cuenta todas las normas de seguridad.","positive":false},{"order":17,"text":"No uso los zapatos de seguridad porque me hacen trabajar incómodo.","positive":false},{"order":18,"text":"Se tendría que ver más la seguridad del trabajo.","positive":true},{"order":19,"text":"Tendría que haber más supervisión en seguridad.","positive":true},{"order":20,"text":"Las normas de seguridad no son problema mío.","positive":false},{"order":21,"text":"Aunque sea más lento prefiero trabajar seguro.","positive":true},{"order":22,"text":"La culpa de los accidentes la tienen las maquinas.","positive":false},{"order":23,"text":"El experto en prevención de riesgos es una persona muy necesaria en toda empresa.","positive":true},{"order":24,"text":"Me uniría a los que luchan para evitar los accidentes de trabajo.","positive":true},{"order":25,"text":"El accidente no avisa, hay que estar alerta.","positive":true},{"order":26,"text":"Si debiese hacerlo, usaría todas las protecciones necesarias.","positive":true},{"order":27,"text":"La seguridad en el trabajo es cuestión de suerte.","positive":false},{"order":28,"text":"A veces uno debe arriesgarse para terminar el trabajo más rápido.","positive":false},{"order":29,"text":"Es imprescindible la buena colaboración de todos para una buena seguridad.","positive":true},{"order":30,"text":"Muchos jefes molestan a la gente hablando de seguridad en el trabajo.","positive":false}]'::jsonb, '{"kind":"prp","positiveItems":[1,2,8,11,14,15,18,19,21,23,24,25,26,29],"factors":{"factor_1":{"items":[23,24,25,26,29],"denominator":25,"mode":"sum"},"factor_2":{"items":[4,6,7,27],"denominator":20,"mode":"sum"},"factor_3":{"items":[1,2,11,15,24],"denominator":25,"mode":"sum"},"factor_4":{"items":[3,9,12,13,20,22],"denominator":30,"mode":"sum"},"factor_5":{"items":[18,19,21],"denominator":15,"mode":"inverse_sum"},"factor_6":{"items":[5,10,16,30],"denominator":20,"mode":"sum"}}}'::jsonb, encode(extensions.digest(convert_to('[{"order":1,"text":"Asistiría a un curso de prevención de accidentes de trabajo.","positive":true},{"order":2,"text":"Colaboraría en las acciones de prevención de accidentes de trabajo.","positive":true},{"order":3,"text":"Asistir a cursos de seguridad es perder el tiempo.","positive":false},{"order":4,"text":"La mayoría de los accidentes de trabajo se deben a mala suerte.","positive":false},{"order":5,"text":"Las reuniones mensuales de seguridad sólo sirven para perder el tiempo.","positive":false},{"order":6,"text":"Por mucho ruido que haya siempre se acostumbra uno.","positive":false},{"order":7,"text":"Cada uno tiene su destino y si se ha de accidentar, por más seguro que trabaje, se accidenta.","positive":false},{"order":8,"text":"Cada trabajador debe pedir su ropa de seguridad cuando le corresponde.","positive":true},{"order":9,"text":"No vale la pena usar protecciones porque el trabajo cunde poco.","positive":false},{"order":10,"text":"Aunque una Herramienta esta defectuosa con cuidado puede utilizarse.","positive":false},{"order":11,"text":"Colaboraría con la confección de carteles de seguridad.","positive":true},{"order":12,"text":"Para prevenirse de los accidentes no es necesario utilizar los elementos de protección personal.","positive":false},{"order":13,"text":"Los accidentes de trabajo solo ocurren a los demás","positive":false},{"order":14,"text":"El trabajador descuidado pone en peligro todos sus compañeros.","positive":true},{"order":15,"text":"Deberían organizarse más campañas de seguridad.","positive":true},{"order":16,"text":"Cuando trabajamos no es posible tener en cuenta todas las normas de seguridad.","positive":false},{"order":17,"text":"No uso los zapatos de seguridad porque me hacen trabajar incómodo.","positive":false},{"order":18,"text":"Se tendría que ver más la seguridad del trabajo.","positive":true},{"order":19,"text":"Tendría que haber más supervisión en seguridad.","positive":true},{"order":20,"text":"Las normas de seguridad no son problema mío.","positive":false},{"order":21,"text":"Aunque sea más lento prefiero trabajar seguro.","positive":true},{"order":22,"text":"La culpa de los accidentes la tienen las maquinas.","positive":false},{"order":23,"text":"El experto en prevención de riesgos es una persona muy necesaria en toda empresa.","positive":true},{"order":24,"text":"Me uniría a los que luchan para evitar los accidentes de trabajo.","positive":true},{"order":25,"text":"El accidente no avisa, hay que estar alerta.","positive":true},{"order":26,"text":"Si debiese hacerlo, usaría todas las protecciones necesarias.","positive":true},{"order":27,"text":"La seguridad en el trabajo es cuestión de suerte.","positive":false},{"order":28,"text":"A veces uno debe arriesgarse para terminar el trabajo más rápido.","positive":false},{"order":29,"text":"Es imprescindible la buena colaboración de todos para una buena seguridad.","positive":true},{"order":30,"text":"Muchos jefes molestan a la gente hablando de seguridad en el trabajo.","positive":false}]','utf8'),'sha256'),'hex'), 4, true)
on conflict(instrument_code,content_version,scoring_version) do update set name=excluded.name,short_name=excluded.short_name,instructions=excluded.instructions,response_options=excluded.response_options,questions=excluded.questions,scoring_key=excluded.scoring_key,content_sha256=excluded.content_sha256,sort_order=excluded.sort_order,is_active=true;

insert into private.psychometric_consent_versions(code,version,title,document_date,body,content_sha256,document_sha256,is_active) values
('F-RH-061','0','Consentimiento Informado Evaluación Psicolaboral','2024-09-09','Las respuestas que entrego en este test psicolaboral, fueron otorgadas bajo mi “consentimiento informado”, además certifico que las respuestas plasmadas en las pruebas yo las entregue de manera conforme.

Autorizo al psicólogo/a organizacional para el uso de la información de manera confidencial, siendo de uso único y exclusivo para el profesional, con la finalidad de entregar los resultados a la empresa.',encode(extensions.digest(convert_to('Las respuestas que entrego en este test psicolaboral, fueron otorgadas bajo mi “consentimiento informado”, además certifico que las respuestas plasmadas en las pruebas yo las entregue de manera conforme.

Autorizo al psicólogo/a organizacional para el uso de la información de manera confidencial, siendo de uso único y exclusivo para el profesional, con la finalidad de entregar los resultados a la empresa.','utf8'),'sha256'),'hex'),'9aa1a9d56f7a83644582ca83f2641cdf98bf945bb7b22425d0b6068647284fdf',true),
('F-RH-062','0','Consentimiento Informado General','2024-09-12','Yo autorizo a la empresa a la cual estoy postulando, a realizar visualización de baterías médicas completas para su posterior entrega por parte del organismo administrador.',encode(extensions.digest(convert_to('Yo autorizo a la empresa a la cual estoy postulando, a realizar visualización de baterías médicas completas para su posterior entrega por parte del organismo administrador.','utf8'),'sha256'),'hex'),'d2cc79217f823a7ac71b0ed3f93ca5d0272ca56dd59815c515b4eb77a826f25a',true)
on conflict(code,version) do update set title=excluded.title,document_date=excluded.document_date,body=excluded.body,content_sha256=excluded.content_sha256,document_sha256=excluded.document_sha256,is_active=true;

create or replace function public.user_can_access_psycholaboral(requested_actor uuid) returns boolean language plpgsql stable security definer set search_path='' as $$
begin
  if requested_actor is null or auth.uid() is distinct from requested_actor then return false; end if;
  return public.user_can_access_module(requested_actor,'gestion_psicolaboral');
end $$;

create or replace function private.jsonb_object_size(payload jsonb) returns integer
language sql immutable strict set search_path='' as $$
  select count(*)::integer from jsonb_object_keys(payload);
$$;
revoke all on function public.user_can_access_psycholaboral(uuid) from public,anon;
grant execute on function public.user_can_access_psycholaboral(uuid) to authenticated;

create or replace function public.get_psycholaboral_catalog() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); payload jsonb;
begin
 if uid is null or not public.user_can_access_psycholaboral(uid) then raise exception 'Sin permisos para Gestión Psicolaboral'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('code',v.instrument_code,'name',v.name,'short_name',v.short_name,'question_count',jsonb_array_length(v.questions),'content_version',v.content_version) order by v.sort_order),'[]'::jsonb) into payload from private.psychometric_instrument_versions v where v.is_active;
 return payload;
end $$;

create or replace function public.get_psycholaboral_candidates_page(p_search text default null,p_status text default null,p_limit integer default 50,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); lim int:=least(greatest(coalesce(p_limit,50),1),100); offv int:=greatest(coalesce(p_offset,0),0); q text:=lower(trim(coalesce(p_search,''))); items jsonb; total bigint;
begin
 if uid is null or not public.user_can_access_psycholaboral(uid) then raise exception 'Sin permisos para Gestión Psicolaboral'; end if;
 with base as (
  select rcc.id,cp.full_name,cp.national_id,coalesce(nullif(lower(trim(cp.personal_email)),''),nullif(lower(trim(cp.email)),'')) email,
    rc.case_code,hr.folio,rc.contract_name,rc.job_position_name,rc.status case_status,rcc.stage_code,rcc.stage_entered_at,
    a.id assessment_id,a.delivery_status,a.execution_status,a.decision,a.created_at assessment_created_at,a.issued_at,a.started_at,a.deadline_at,a.completed_at,a.certificate_status,a.certificate_path,
    coalesce((select jsonb_agg(jsonb_build_object('code',v.instrument_code,'name',v.short_name,'status',ai.status,'answered',private.jsonb_object_size(ai.responses),'total',jsonb_array_length(v.questions)) order by ai.sort_order) from private.psychometric_assessment_instruments ai join private.psychometric_instrument_versions v on v.id=ai.instrument_version_id where ai.assessment_id=a.id),'[]'::jsonb) instruments
  from public.recruitment_case_candidates rcc join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id join public.hiring_requests hr on hr.id=rc.hiring_request_id join public.candidate_profiles cp on cp.id=rcc.candidate_profile_id
  left join lateral (select pa.* from private.psychometric_assessments pa where pa.recruitment_case_candidate_id=rcc.id and not (pa.delivery_status='failed' and pa.execution_status='cancelled') order by pa.created_at desc limit 1) a on true
  where rc.status not in ('filled','closed_unfilled','cancelled') and rcc.stage_code not in ('hired','rejected','withdrawn')
 ), filtered as (select *,case when assessment_id is null then 'not_sent' when execution_status='completed' then 'completed' else 'sent' end display_status from base where (q='' or lower(concat_ws(' ',full_name,national_id,email,case_code,folio::text,contract_name,job_position_name)) like '%'||q||'%')),
 selected as (select * from filtered where nullif(trim(coalesce(p_status,'')),'') is null or display_status=p_status)
 select coalesce(jsonb_agg(to_jsonb(p) order by p.assessment_created_at desc nulls last,p.full_name),'[]'::jsonb),(select count(*) from selected) into items,total from (select * from selected order by assessment_created_at desc nulls last,full_name limit lim offset offv) p;
 return jsonb_build_object('items',coalesce(items,'[]'::jsonb),'total_count',coalesce(total,0));
end $$;

create or replace function public.prepare_psycholaboral_dispatch(p_case_candidate_id uuid,p_instrument_codes text[],p_invite_hash text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); rec record; aid uuid; pid uuid; selected_count int;
begin
 if uid is null or not public.user_can_access_psycholaboral(uid) then raise exception 'Sin permisos para Gestión Psicolaboral'; end if;
 if coalesce(cardinality(p_instrument_codes),0)=0 or cardinality(p_instrument_codes)>4 then raise exception 'Selecciona al menos un test válido'; end if;
 if length(trim(coalesce(p_invite_hash,'')))<>64 or length(trim(coalesce(p_idempotency_key,'')))<16 then raise exception 'Solicitud inválida'; end if;
 select rcc.id,cp.full_name,cp.national_id,coalesce(nullif(lower(trim(cp.personal_email)),''),nullif(lower(trim(cp.email)),'')) email,rc.case_code,hr.folio,rc.contract_name,rc.job_position_name into rec
 from public.recruitment_case_candidates rcc join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id join public.hiring_requests hr on hr.id=rc.hiring_request_id join public.candidate_profiles cp on cp.id=rcc.candidate_profile_id
 where rcc.id=p_case_candidate_id and rc.status not in ('filled','closed_unfilled','cancelled') and rcc.stage_code not in ('hired','rejected','withdrawn') for update of rcc;
 if rec.id is null then raise exception 'El candidato ya no tiene un proceso activo'; end if;
 if rec.email is null or rec.email !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'El candidato no tiene un correo válido'; end if;
 select count(*) into selected_count from private.psychometric_instrument_versions v where v.is_active and v.instrument_code=any(p_instrument_codes);
 if selected_count<>cardinality(p_instrument_codes) or selected_count<>cardinality(array(select distinct unnest(p_instrument_codes))) then raise exception 'La batería contiene test inválidos o repetidos'; end if;
 insert into private.psychometric_assessments(recruitment_case_candidate_id,email_snapshot,invite_hash,invite_expires_at,idempotency_key,created_by) values(rec.id,rec.email,p_invite_hash,timezone('utc',now())+interval '72 hours',p_idempotency_key,uid)
 on conflict(created_by,idempotency_key) do update set updated_at=timezone('utc',now()) returning id,public_id into aid,pid;
 if not exists(select 1 from private.psychometric_assessment_instruments where assessment_id=aid) then
  insert into private.psychometric_assessment_instruments(assessment_id,instrument_version_id,sort_order)
  select aid,v.id,row_number() over(order by array_position(p_instrument_codes,v.instrument_code)) from private.psychometric_instrument_versions v where v.is_active and v.instrument_code=any(p_instrument_codes);
 end if;
 if not exists(select 1 from private.psychometric_assessment_consents where assessment_id=aid) then
  insert into private.psychometric_assessment_consents(assessment_id,consent_version_id,sort_order)
  select aid,c.id,row_number() over(order by c.code) from private.psychometric_consent_versions c where c.is_active;
 end if;
 insert into private.psychometric_audit_log(assessment_id,event_type,actor_user_id,metadata) values(aid,'dispatch_prepared',uid,jsonb_build_object('instrument_count',selected_count));
 return jsonb_build_object('assessment_id',aid,'public_id',pid,'email',rec.email,'candidate_name',rec.full_name,'rut',rec.national_id,'case_code',rec.case_code,'folio',rec.folio,'contract_name',rec.contract_name,'job_position_name',rec.job_position_name);
end $$;

create or replace function public.finalize_psycholaboral_dispatch(p_assessment_id uuid,p_success boolean,p_provider_message_id text default null,p_error text default null) returns void language plpgsql security definer set search_path='' as $$
declare updated_id uuid;
begin
 update private.psychometric_assessments set delivery_status=case when p_success then 'sent' else 'failed' end,execution_status=case when p_success then execution_status else 'cancelled' end,issued_at=case when p_success then timezone('utc',now()) else issued_at end,provider_message_id=case when p_success then nullif(trim(p_provider_message_id),'') else provider_message_id end,last_error=case when p_success then null else left(coalesce(p_error,'Error de entrega'),500) end,updated_at=timezone('utc',now()) where id=p_assessment_id and delivery_status='preparing' and execution_status='not_started' returning id into updated_id;
 if updated_id is null then raise exception 'La entrega ya fue finalizada'; end if;
 insert into private.psychometric_audit_log(assessment_id,event_type,metadata) values(p_assessment_id,case when p_success then 'email_sent' else 'email_failed' end,'{}');
end $$;

create or replace function public.redeem_psycholaboral_invite(p_public_id uuid,p_rut text,p_invite_hash text,p_session_hash text,p_ip_hash text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a private.psychometric_assessments%rowtype; expected_rut text:=regexp_replace(upper(coalesce(p_rut,'')),'[^0-9K]','','g'); actual_rut text; scope text:='ip:'||left(coalesce(p_ip_hash,'unknown'),64); attempts int; nowv timestamptz:=timezone('utc',now());
begin
 insert into private.psychometric_access_rate_limits(scope_key,window_started_at,attempt_count,updated_at) values(scope,nowv,1,nowv) on conflict(scope_key) do update set attempt_count=case when private.psychometric_access_rate_limits.window_started_at<nowv-interval '15 minutes' then 1 else private.psychometric_access_rate_limits.attempt_count+1 end,window_started_at=case when private.psychometric_access_rate_limits.window_started_at<nowv-interval '15 minutes' then nowv else private.psychometric_access_rate_limits.window_started_at end,updated_at=nowv returning attempt_count into attempts;
 if attempts>8 then return jsonb_build_object('access_denied',true); end if;
 select * into a from private.psychometric_assessments where public_id=p_public_id for update;
 if a.id is null or a.delivery_status<>'sent' or a.invite_consumed_at is not null or a.invite_hash<>p_invite_hash or a.invite_expires_at<=nowv then return jsonb_build_object('access_denied',true); end if;
 select regexp_replace(upper(coalesce(cp.national_id,'')),'[^0-9K]','','g') into actual_rut from public.recruitment_case_candidates rcc join public.candidate_profiles cp on cp.id=rcc.candidate_profile_id join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id where rcc.id=a.recruitment_case_candidate_id and rc.status not in ('filled','closed_unfilled','cancelled') and rcc.stage_code not in ('hired','rejected','withdrawn');
 if actual_rut is null or actual_rut<>expected_rut or length(p_session_hash)<>64 then return jsonb_build_object('access_denied',true); end if;
 update private.psychometric_assessments set invite_consumed_at=nowv,session_hash=p_session_hash,started_at=nowv,deadline_at=nowv+interval '90 minutes',execution_status='in_progress',updated_at=nowv where id=a.id;
 insert into private.psychometric_audit_log(assessment_id,event_type,metadata) values(a.id,'session_started',jsonb_build_object('deadline_at',nowv+interval '90 minutes'));
 return public.get_psycholaboral_candidate_session(p_session_hash);
end $$;

create or replace function public.get_psycholaboral_candidate_session(p_session_hash text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a private.psychometric_assessments%rowtype; candidate jsonb; consents jsonb; accepted_count int; instruments jsonb;
begin
 select * into a from private.psychometric_assessments where session_hash=p_session_hash for update;
 if a.id is null or a.execution_status not in ('in_progress','completed') then raise exception 'La sesión no es válida'; end if;
 if a.execution_status<>'completed' and a.deadline_at<=timezone('utc',now()) then update private.psychometric_assessments set execution_status='expired',updated_at=timezone('utc',now()) where id=a.id; return jsonb_build_object('assessment_id',a.id,'public_id',a.public_id,'execution_status','expired','deadline_at',a.deadline_at,'consents','[]'::jsonb,'consents_accepted',false,'instruments','[]'::jsonb); end if;
 if not exists(select 1 from public.recruitment_case_candidates rcc join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id where rcc.id=a.recruitment_case_candidate_id and rc.status not in ('filled','closed_unfilled','cancelled') and rcc.stage_code not in ('hired','rejected','withdrawn')) then update private.psychometric_assessments set execution_status='cancelled',updated_at=timezone('utc',now()) where id=a.id; return jsonb_build_object('assessment_id',a.id,'public_id',a.public_id,'execution_status','cancelled','consents','[]'::jsonb,'consents_accepted',false,'instruments','[]'::jsonb); end if;
 select jsonb_build_object('full_name',cp.full_name,'national_id',cp.national_id,'job_position_name',rc.job_position_name,'contract_name',rc.contract_name) into candidate from public.recruitment_case_candidates rcc join public.candidate_profiles cp on cp.id=rcc.candidate_profile_id join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id where rcc.id=a.recruitment_case_candidate_id;
 select coalesce(jsonb_agg(jsonb_build_object('code',c.code,'version',c.version,'title',c.title,'body',c.body,'document_sha256',c.document_sha256,'accepted',ca.id is not null) order by ac.sort_order),'[]'::jsonb),count(ca.id) into consents,accepted_count from private.psychometric_assessment_consents ac join private.psychometric_consent_versions c on c.id=ac.consent_version_id left join private.psychometric_consent_acceptances ca on ca.consent_version_id=c.id and ca.assessment_id=a.id where ac.assessment_id=a.id;
 if accepted_count=(select count(*) from private.psychometric_assessment_consents where assessment_id=a.id) then select coalesce(jsonb_agg(jsonb_build_object('code',v.instrument_code,'name',v.name,'short_name',v.short_name,'instructions',v.instructions,'options',v.response_options,'questions',(select jsonb_agg(jsonb_build_object('order',q.value->'order','text',q.value->'text') order by (q.value->>'order')::int) from jsonb_array_elements(v.questions)q),'status',ai.status,'responses',ai.responses,'revision',ai.response_revision) order by ai.sort_order),'[]'::jsonb) into instruments from private.psychometric_assessment_instruments ai join private.psychometric_instrument_versions v on v.id=ai.instrument_version_id where ai.assessment_id=a.id; else instruments:='[]'::jsonb; end if;
 return jsonb_build_object('assessment_id',a.id,'public_id',a.public_id,'candidate',candidate,'deadline_at',a.deadline_at,'execution_status',a.execution_status,'consents',consents,'consents_accepted',accepted_count=(select count(*) from private.psychometric_assessment_consents where assessment_id=a.id),'instruments',instruments);
end $$;

create or replace function public.accept_psycholaboral_consents(p_session_hash text,p_consents jsonb,p_ip_hash text,p_user_agent_hash text) returns jsonb language plpgsql security definer set search_path='' as $$
declare aid uuid; expected_count int; matched_count int;
begin
 select id into aid from private.psychometric_assessments where session_hash=p_session_hash and execution_status='in_progress' and deadline_at>timezone('utc',now()) for update;
 if aid is null then raise exception 'La sesión no es válida'; end if;
 if jsonb_typeof(p_consents)<>'array' then raise exception 'Debes aceptar los consentimientos mostrados'; end if;
 select count(*) into expected_count from private.psychometric_assessment_consents where assessment_id=aid;
 select count(distinct c.id) into matched_count from jsonb_array_elements(p_consents) supplied join private.psychometric_assessment_consents ac on ac.assessment_id=aid join private.psychometric_consent_versions c on c.id=ac.consent_version_id and c.code=supplied->>'code' and c.version=supplied->>'version' and c.document_sha256=supplied->>'document_sha256' where coalesce((supplied->>'accepted')::boolean,false);
 if expected_count=0 or matched_count<>expected_count or jsonb_array_length(p_consents)<>expected_count then raise exception 'Los consentimientos cambiaron; recarga la página'; end if;
 insert into private.psychometric_consent_acceptances(assessment_id,consent_version_id,ip_hash,user_agent_hash) select aid,ac.consent_version_id,left(p_ip_hash,64),left(p_user_agent_hash,64) from private.psychometric_assessment_consents ac where ac.assessment_id=aid on conflict do nothing;
 insert into private.psychometric_audit_log(assessment_id,event_type,metadata) values(aid,'consents_accepted',jsonb_build_object('consent_count',expected_count));
 return public.get_psycholaboral_candidate_session(p_session_hash);
end $$;

create or replace function private.score_psychometric_instrument(p_version_id uuid,p_responses jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v private.psychometric_instrument_versions%rowtype; q jsonb; ord int; val numeric; score numeric; code text; bucket jsonb:='{}'; item_count int:=0; result jsonb; rec record; total numeric:=0; params jsonb; warm numeric:=0; dominance numeric:=0; factor jsonb; fsum numeric; fname text;
begin
 select * into v from private.psychometric_instrument_versions where id=p_version_id;
 if v.id is null then raise exception 'Instrumento inválido'; end if;
 if jsonb_typeof(p_responses)<>'object' or private.jsonb_object_size(p_responses)<>jsonb_array_length(v.questions) then raise exception 'Debes responder todas las preguntas'; end if;
 for q in select value from jsonb_array_elements(v.questions) loop
  ord:=(q->>'order')::int; if not (p_responses ? ord::text) or jsonb_typeof(p_responses->ord::text)<>'number' then raise exception 'Respuesta inválida'; end if; val:=(p_responses->>ord::text)::numeric;
  if not exists(select 1 from jsonb_array_elements(v.response_options)o where (o->>'value')::numeric=val) then raise exception 'Respuesta fuera de rango'; end if;
  code:=coalesce(q->>'code','TOTAL');
  if v.instrument_code='IPIP16_105' then score:=case when coalesce((q->>'reverse')::boolean,false) then 6-val else val end;
  elsif v.instrument_code='IPIP_IPC_32' then score:=case when coalesce((q->>'reverse')::boolean,false) then 6-val else val end;
  elsif v.instrument_code='BARRATT_BIS11_30' then score:=case when coalesce((q->>'reverse')::boolean,false) then 4-val else val end;
  else score:=case when coalesce((q->>'positive')::boolean,false) then 6-val else val end; end if;
  bucket:=jsonb_set(bucket,array[code],jsonb_build_object('sum',coalesce((bucket->code->>'sum')::numeric,0)+score,'count',coalesce((bucket->code->>'count')::int,0)+1),true); total:=total+score; item_count:=item_count+1;
 end loop;
 if v.instrument_code='IPIP16_105' then
  result:=jsonb_build_object('kind','ipip16','dimensions',(select jsonb_object_agg(e.key,jsonb_build_object('name',(select x->>'name' from jsonb_array_elements(v.scoring_key->'scales')x where x->>'code'=e.key),'sum',(e.value->>'sum')::numeric,'mean',round((e.value->>'sum')::numeric/(e.value->>'count')::numeric,4),'item_count',(e.value->>'count')::int)) from jsonb_each(bucket)e),'norm_status','not_available');
 elsif v.instrument_code='IPIP_IPC_32' then
  params:=v.scoring_key->'params';
  for rec in select e.key,(e.value->>'sum')::numeric/(e.value->>'count')::numeric mean from jsonb_each(bucket)e loop val:=(rec.mean-(params->rec.key->>'mean')::numeric)/(params->rec.key->>'sd')::numeric; warm:=warm+val*cos(radians((params->rec.key->>'angle')::numeric)); dominance:=dominance+val*sin(radians((params->rec.key->>'angle')::numeric)); end loop;
  result:=jsonb_build_object('kind','ipc32','octants',(select jsonb_object_agg(e.key,jsonb_build_object('name',params->e.key->>'name','mean',round((e.value->>'sum')::numeric/(e.value->>'count')::numeric,4))) from jsonb_each(bucket)e),'warmth',round(0.3*warm,4),'dominance',round(0.3*dominance,4),'norm_status','reference_not_chilean');
 elsif v.instrument_code='BARRATT_BIS11_30' then
  result:=jsonb_build_object('kind','barratt','total',total,'classification',case when total<=33 then 'Bajo el promedio' when total<=64 then 'Promedio' else 'Sobre el promedio' end);
 else
  result:=jsonb_build_object('kind','prp','raw_total',total,'norm_status','pending_professional_review','factors','{}'::jsonb);
  for fname,factor in select key,value from jsonb_each(v.scoring_key->'factors') loop select sum(case when coalesce((qv->>'positive')::boolean,false) then 6-(p_responses->>(qv->>'order'))::numeric else (p_responses->>(qv->>'order'))::numeric end) into fsum from jsonb_array_elements(v.questions)qv where (qv->>'order')::int in(select jsonb_array_elements_text(factor->'items')::int); result:=jsonb_set(result,array['factors',fname],to_jsonb(case when factor->>'mode'='inverse_sum' then (15-fsum)/(factor->>'denominator')::numeric else fsum/(factor->>'denominator')::numeric end),true); end loop;
 end if;
 return result||jsonb_build_object('answered',item_count,'content_version',v.content_version,'scoring_version',v.scoring_version);
end $$;

create or replace function public.save_psycholaboral_responses(p_session_hash text,p_instrument_code text,p_responses jsonb,p_expected_revision int) returns jsonb language plpgsql security definer set search_path='' as $$
declare aid uuid; iid uuid; vid uuid; rev int; allowed_count int; qcount int;
begin
 select id into aid from private.psychometric_assessments where session_hash=p_session_hash and execution_status='in_progress' and deadline_at>timezone('utc',now()) for update;
 if aid is null then raise exception 'La sesión no es válida'; end if;
 if exists(select 1 from private.psychometric_assessment_consents ac where ac.assessment_id=aid and not exists(select 1 from private.psychometric_consent_acceptances ca where ca.assessment_id=aid and ca.consent_version_id=ac.consent_version_id)) then raise exception 'Debes aceptar los consentimientos antes de responder'; end if;
 select ai.id,ai.instrument_version_id,ai.response_revision,jsonb_array_length(v.questions) into iid,vid,rev,qcount from private.psychometric_assessment_instruments ai join private.psychometric_instrument_versions v on v.id=ai.instrument_version_id where ai.assessment_id=aid and v.instrument_code=p_instrument_code for update;
 if iid is null or rev<>p_expected_revision or jsonb_typeof(p_responses)<>'object' or private.jsonb_object_size(p_responses)>qcount then raise exception 'Las respuestas cambiaron; recarga la evaluación'; end if;
 select count(*) into allowed_count from jsonb_each(p_responses)e join jsonb_array_elements((select response_options from private.psychometric_instrument_versions where id=vid))o on (o->>'value')::numeric=(e.value#>>'{}')::numeric join jsonb_array_elements((select questions from private.psychometric_instrument_versions where id=vid))q on (q->>'order')::text=e.key where e.key~'^[0-9]+$'; if allowed_count<>private.jsonb_object_size(p_responses) then raise exception 'Respuesta inválida'; end if;
 update private.psychometric_assessment_instruments set responses=p_responses,response_revision=response_revision+1,status=case when private.jsonb_object_size(p_responses)>0 then 'in_progress' else status end,started_at=coalesce(started_at,timezone('utc',now())),updated_at=timezone('utc',now()) where id=iid returning response_revision into rev;
 return jsonb_build_object('revision',rev,'saved',true);
end $$;

create or replace function public.submit_psycholaboral_instrument(p_session_hash text,p_instrument_code text,p_responses jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare a private.psychometric_assessments%rowtype; iid uuid; vid uuid; result jsonb; remaining int;
begin
 select * into a from private.psychometric_assessments where session_hash=p_session_hash for update;
 if a.id is null or a.execution_status not in ('in_progress','completed') or (a.execution_status='in_progress' and a.deadline_at<=timezone('utc',now())) then raise exception 'La sesión no es válida'; end if;
 if exists(select 1 from private.psychometric_assessment_consents ac where ac.assessment_id=a.id and not exists(select 1 from private.psychometric_consent_acceptances ca where ca.assessment_id=a.id and ca.consent_version_id=ac.consent_version_id)) then raise exception 'Debes aceptar los consentimientos antes de responder'; end if;
 select ai.id,ai.instrument_version_id into iid,vid from private.psychometric_assessment_instruments ai join private.psychometric_instrument_versions v on v.id=ai.instrument_version_id where ai.assessment_id=a.id and v.instrument_code=p_instrument_code for update;
 if iid is null then raise exception 'Instrumento inválido'; end if;
 if exists(select 1 from private.psychometric_assessment_instruments where id=iid and status='completed') then return public.get_psycholaboral_candidate_session(p_session_hash); end if;
 result:=private.score_psychometric_instrument(vid,p_responses);
 update private.psychometric_assessment_instruments set responses=p_responses,response_sha256=encode(extensions.digest(convert_to(p_responses::text,'utf8'),'sha256'),'hex'),result=result,result_sha256=encode(extensions.digest(convert_to(result::text,'utf8'),'sha256'),'hex'),status='completed',completed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=iid;
 select count(*) into remaining from private.psychometric_assessment_instruments where assessment_id=a.id and status<>'completed';
 if remaining=0 then update private.psychometric_assessments set execution_status='completed',completed_at=timezone('utc',now()),certificate_status='queued',updated_at=timezone('utc',now()) where id=a.id; insert into private.psychometric_audit_log(assessment_id,event_type,metadata) values(a.id,'assessment_completed',jsonb_build_object('instrument_count',(select count(*) from private.psychometric_assessment_instruments where assessment_id=a.id))); end if;
 return public.get_psycholaboral_candidate_session(p_session_hash);
end $$;

create or replace function public.decide_psycholaboral_assessment(p_assessment_id uuid,p_decision text,p_comment text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); a private.psychometric_assessments%rowtype; commentv text:=nullif(trim(coalesce(p_comment,'')),'');
begin
 if uid is null or not public.user_can_access_psycholaboral(uid) then raise exception 'Sin permisos para Gestión Psicolaboral'; end if;
 if p_decision not in ('approved','rejected') then raise exception 'Decisión inválida'; end if;
 select * into a from private.psychometric_assessments where id=p_assessment_id for update;
 if a.id is null or a.execution_status<>'completed' or a.decision<>'pending' then raise exception 'La evaluación no está disponible para decidir'; end if;
 if p_decision='rejected' and commentv is null then raise exception 'Debes indicar el motivo del rechazo'; end if;
 if p_decision='rejected' then perform public.advance_recruitment_candidate_stage(a.recruitment_case_candidate_id,'rejected',commentv); end if;
 update private.psychometric_assessments set decision=p_decision,decided_at=timezone('utc',now()),decided_by=uid,updated_at=timezone('utc',now()) where id=a.id;
 insert into private.psychometric_audit_log(assessment_id,event_type,actor_user_id,metadata) values(a.id,'decision_'||p_decision,uid,jsonb_build_object('comment_present',commentv is not null));
 return jsonb_build_object('assessment_id',a.id,'decision',p_decision);
end $$;

create or replace function public.get_psycholaboral_result_detail(p_assessment_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); payload jsonb;
begin
 if uid is null or not public.user_can_access_psycholaboral(uid) then raise exception 'Sin permisos para Gestión Psicolaboral'; end if;
 select jsonb_build_object('assessment_id',a.id,'candidate',jsonb_build_object('full_name',cp.full_name,'national_id',cp.national_id,'job_position_name',rc.job_position_name,'contract_name',rc.contract_name),'execution_status',a.execution_status,'decision',a.decision,'completed_at',a.completed_at,'certificate_status',a.certificate_status,'certificate_available',a.certificate_status='generated','instruments',coalesce((select jsonb_agg(jsonb_build_object('code',v.instrument_code,'name',v.name,'result',ai.result,'response_count',private.jsonb_object_size(ai.responses),'response_distribution',(select jsonb_object_agg(distribution.value,distribution.response_count) from (select response.value,count(*) as response_count from jsonb_each_text(ai.responses) response group by response.value) distribution)) order by ai.sort_order) from private.psychometric_assessment_instruments ai join private.psychometric_instrument_versions v on v.id=ai.instrument_version_id where ai.assessment_id=a.id),'[]'::jsonb)) into payload from private.psychometric_assessments a join public.recruitment_case_candidates rcc on rcc.id=a.recruitment_case_candidate_id join public.candidate_profiles cp on cp.id=rcc.candidate_profile_id join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id where a.id=p_assessment_id;
 if payload is null then raise exception 'Evaluación no encontrada'; end if; return payload;
end $$;

create or replace function public.get_psycholaboral_certificate_artifact(p_assessment_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); payload jsonb;
begin
 if uid is null or not public.user_can_access_psycholaboral(uid) then raise exception 'Sin permisos para Gestión Psicolaboral'; end if;
 select jsonb_build_object('bucket',a.certificate_bucket,'path',a.certificate_path,'sha256',a.certificate_sha256)
 into payload from private.psychometric_assessments a
 where a.id=p_assessment_id and a.certificate_status='generated' and a.certificate_bucket is not null and a.certificate_path is not null;
 if payload is null then raise exception 'El certificado todavía no está disponible'; end if;
 return payload;
end $$;

create or replace function public.get_psycholaboral_certificate_payload(p_assessment_id uuid,p_claim_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare payload jsonb; claimed uuid;
begin
 update private.psychometric_assessments set certificate_status='processing',certificate_claim_token=p_claim_token,certificate_claimed_at=timezone('utc',now()),updated_at=timezone('utc',now()) where id=p_assessment_id and execution_status='completed' and (certificate_status in ('queued','failed') or (certificate_status='processing' and certificate_claimed_at<timezone('utc',now())-interval '10 minutes')) returning id into claimed;
 if claimed is null then raise exception 'El certificado ya fue procesado o está en ejecución'; end if;
 select jsonb_build_object(
  'assessment_id',a.id,
  'public_id',a.public_id,
  'completed_at',a.completed_at,
  'candidate',jsonb_build_object('full_name',cp.full_name,'national_id',cp.national_id,'job_position_name',rc.job_position_name,'contract_name',rc.contract_name,'case_code',rc.case_code,'company_name',coalesce((select bcm.company_name from public.buk_contract_mappings bcm where bcm.contract_id=rc.contract_id and bcm.is_operational order by bcm.is_one_to_one desc,bcm.updated_at desc limit 1),'Buses JM')),
  'instruments',(
   select jsonb_agg(jsonb_build_object(
    'code',v.instrument_code,
    'name',v.name,
    'result',ai.result,
    'response_count',private.jsonb_object_size(ai.responses),
    'response_summary',(
     select jsonb_agg(jsonb_build_object(
      'label',option_item->>'label',
      'count',(select count(*) from jsonb_each_text(ai.responses) response where response.value::numeric=(option_item->>'value')::numeric)
     ) order by (option_item->>'value')::numeric)
     from jsonb_array_elements(v.response_options) option_item
    ),
    'result_sha256',ai.result_sha256
   ) order by ai.sort_order)
   from private.psychometric_assessment_instruments ai
   join private.psychometric_instrument_versions v on v.id=ai.instrument_version_id
   where ai.assessment_id=a.id
  ),
  'consents',(
   select jsonb_agg(jsonb_build_object('code',c.code,'version',c.version,'document_sha256',c.document_sha256,'accepted_at',ca.accepted_at) order by c.code)
   from private.psychometric_consent_acceptances ca
   join private.psychometric_consent_versions c on c.id=ca.consent_version_id
   where ca.assessment_id=a.id
  )
 ) into payload
 from private.psychometric_assessments a
 join public.recruitment_case_candidates rcc on rcc.id=a.recruitment_case_candidate_id
 join public.candidate_profiles cp on cp.id=rcc.candidate_profile_id
 join public.recruitment_cases rc on rc.id=rcc.recruitment_case_id
 where a.id=p_assessment_id and a.execution_status='completed';
 if payload is null then raise exception 'Evaluación no disponible'; end if; return payload; end $$;

create or replace function public.complete_psycholaboral_certificate(p_assessment_id uuid,p_claim_token uuid,p_success boolean,p_bucket text default null,p_path text default null,p_sha256 text default null,p_error text default null) returns void language plpgsql security definer set search_path='' as $$
declare updated_id uuid;
begin update private.psychometric_assessments set certificate_status=case when p_success then 'generated' else 'failed' end,certificate_bucket=case when p_success then p_bucket else certificate_bucket end,certificate_path=case when p_success then p_path else certificate_path end,certificate_sha256=case when p_success then p_sha256 else certificate_sha256 end,certificate_generated_at=case when p_success then timezone('utc',now()) else certificate_generated_at end,certificate_claim_token=null,certificate_claimed_at=null,last_error=case when p_success then null else left(coalesce(p_error,'Error de certificado'),500) end,updated_at=timezone('utc',now()) where id=p_assessment_id and certificate_status='processing' and certificate_claim_token=p_claim_token returning id into updated_id; if updated_id is null then raise exception 'Claim de certificado inválido'; end if; insert into private.psychometric_audit_log(assessment_id,event_type,metadata) values(p_assessment_id,case when p_success then 'certificate_generated' else 'certificate_failed' end,'{}'); end $$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('psychometric_documents','psychometric_documents',false,10485760,array['application/pdf']::text[]) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

drop policy if exists psychometric_documents_select_authorized on storage.objects;
-- No direct authenticated reads: the Edge Function authorizes one assessment and
-- returns a 60-second signed URL. This prevents module users from browsing paths.

revoke all on function public.get_psycholaboral_catalog() from public,anon; grant execute on function public.get_psycholaboral_catalog() to authenticated;
revoke all on function public.get_psycholaboral_candidates_page(text,text,integer,integer) from public,anon; grant execute on function public.get_psycholaboral_candidates_page(text,text,integer,integer) to authenticated;
revoke all on function public.prepare_psycholaboral_dispatch(uuid,text[],text,text) from public,anon; grant execute on function public.prepare_psycholaboral_dispatch(uuid,text[],text,text) to authenticated;
revoke all on function public.decide_psycholaboral_assessment(uuid,text,text) from public,anon; grant execute on function public.decide_psycholaboral_assessment(uuid,text,text) to authenticated;
revoke all on function public.get_psycholaboral_result_detail(uuid) from public,anon; grant execute on function public.get_psycholaboral_result_detail(uuid) to authenticated;
revoke all on function public.get_psycholaboral_certificate_artifact(uuid) from public,anon; grant execute on function public.get_psycholaboral_certificate_artifact(uuid) to authenticated;
revoke all on function public.finalize_psycholaboral_dispatch(uuid,boolean,text,text) from public,anon,authenticated; grant execute on function public.finalize_psycholaboral_dispatch(uuid,boolean,text,text) to service_role;
revoke all on function public.redeem_psycholaboral_invite(uuid,text,text,text,text) from public,anon,authenticated; grant execute on function public.redeem_psycholaboral_invite(uuid,text,text,text,text) to service_role;
revoke all on function public.get_psycholaboral_candidate_session(text) from public,anon,authenticated; grant execute on function public.get_psycholaboral_candidate_session(text) to service_role;
revoke all on function public.accept_psycholaboral_consents(text,jsonb,text,text) from public,anon,authenticated; grant execute on function public.accept_psycholaboral_consents(text,jsonb,text,text) to service_role;
revoke all on function public.save_psycholaboral_responses(text,text,jsonb,integer) from public,anon,authenticated; grant execute on function public.save_psycholaboral_responses(text,text,jsonb,integer) to service_role;
revoke all on function public.submit_psycholaboral_instrument(text,text,jsonb) from public,anon,authenticated; grant execute on function public.submit_psycholaboral_instrument(text,text,jsonb) to service_role;
revoke all on function public.get_psycholaboral_certificate_payload(uuid,uuid) from public,anon,authenticated; grant execute on function public.get_psycholaboral_certificate_payload(uuid,uuid) to service_role;
revoke all on function public.complete_psycholaboral_certificate(uuid,uuid,boolean,text,text,text,text) from public,anon,authenticated; grant execute on function public.complete_psycholaboral_certificate(uuid,uuid,boolean,text,text,text,text) to service_role;
revoke all on function private.score_psychometric_instrument(uuid,jsonb) from public,anon,authenticated; grant execute on function private.score_psychometric_instrument(uuid,jsonb) to service_role;
revoke all on function private.jsonb_object_size(jsonb) from public,anon,authenticated; grant execute on function private.jsonb_object_size(jsonb) to service_role;

notify pgrst,'reload schema';
commit;
